{"file_path":"src/parse.js","content":"/**
 * Parsing of the election description read from standard input into a
 * declared candidate set and a list of ballots.
 */

const NAME_PATTERN = /^[A-Za-z0-9_-]+$/
const COUNT_PATTERN = /^[1-9][0-9]*$/

/** Raised for any malformed election input, carrying the offending line. */
export class ParseError extends Error {
  constructor(line, message) {
    super(message)
    this.line = line
  }
}

/**
 * Parses election text into `{ candidates, ballots }`, where `candidates`
 * is the array of declared names and `ballots` is an array of
 * `{ count: bigint, names: string[] }` in the order they were declared.
 * Throws `ParseError` on the first malformed line.
 */
export function parseElection(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  let candidatesDeclared = false
  let candidateSet = new Set()
  const ballots = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const word = tokens[0]

    if (word === 'candidates') {
      if (candidatesDeclared) {
        throw new ParseError(lineNo, 'candidates must be declared once, before any ballot')
      }
      if (tokens.length < 2) {
        throw new ParseError(lineNo, 'expected candidates <name>...')
      }
      const seen = new Set()
      for (const name of tokens.slice(1)) {
        if (!NAME_PATTERN.test(name)) {
          throw new ParseError(lineNo, `invalid candidate name ${name}`)
        }
        if (seen.has(name)) {
          throw new ParseError(lineNo, `candidate ${name} is declared twice`)
        }
        seen.add(name)
      }
      candidateSet = seen
      candidatesDeclared = true
    } else if (word === 'ballot') {
      if (!candidatesDeclared) {
        throw new ParseError(lineNo, 'candidates must be declared once, before any ballot')
      }
      if (tokens.length < 3) {
        throw new ParseError(lineNo, 'expected ballot <count> <candidate>...')
      }
      if (!COUNT_PATTERN.test(tokens[1])) {
        throw new ParseError(lineNo, 'count must be a positive integer')
      }
      const seen = new Set()
      const names = []
      for (const name of tokens.slice(2)) {
        if (!candidateSet.has(name)) {
          throw new ParseError(lineNo, `unknown candidate ${name}`)
        }
        if (seen.has(name)) {
          throw new ParseError(lineNo, `candidate ${name} is repeated`)
        }
        seen.add(name)
        names.push(name)
      }
      ballots.push({ count: BigInt(tokens[1]), names })
    } else {
      throw new ParseError(lineNo, `unknown directive ${word}`)
    }
  }

  if (!candidatesDeclared) {
    throw new ParseError(null, 'no candidates')
  }

  return { candidates: [...candidateSet], ballots }
}
"}

