{"file_path":"src/count.js","content":"/**
 * The instant-runoff count itself: repeatedly tallying continuing
 * candidates' first choices, declaring a winner at a majority, or
 * eliminating the candidate with the fewest votes and trying again.
 */

/**
 * Runs the count. Returns `{ rounds, winner }`, where `rounds` is an array
 * of `{ counts, exhausted, eliminated }` (one per round counted, in order,
 * `counts` a `Map<string, bigint>` over that round's continuing candidates,
 * `eliminated` the name removed after that round or `null`) and `winner`
 * is the winning name or `null` if none was reached.
 */
export function countElection(candidates, ballots) {
  let continuing = new Set(candidates)
  const rounds = []
  let winner = null

  for (;;) {
    const counts = new Map()
    for (const name of continuing) counts.set(name, 0n)

    let activeTotal = 0n
    let exhausted = 0n
    for (const ballot of ballots) {
      const pick = ballot.names.find((name) => continuing.has(name))
      if (pick === undefined) {
        exhausted += ballot.count
      } else {
        counts.set(pick, counts.get(pick) + ballot.count)
        activeTotal += ballot.count
      }
    }

    const round = { counts, exhausted, eliminated: null }
    rounds.push(round)

    if (activeTotal === 0n) break

    const majorityWinner = [...continuing].find((name) => counts.get(name) * 2n > activeTotal)
    if (majorityWinner !== undefined) {
      winner = majorityWinner
      break
    }

    let fewest = null
    for (const name of continuing) {
      const votes = counts.get(name)
      if (fewest === null || votes < fewest) fewest = votes
    }
    const tied = [...continuing].filter((name) => counts.get(name) === fewest)
    const eliminated = tied.length === 1 ? tied[0] : breakTie(tied, rounds)

    round.eliminated = eliminated
    continuing.delete(eliminated)
  }

  return { rounds, winner }
}

/**
 * Resolves an elimination tie by comparing the tied candidates' vote
 * counts round by round from the first round onwards, narrowing to
 * whoever had the fewest at the first round that separates them, and
 * falling back to picking whoever's name sorts last by code point.
 */
function breakTie(tied, rounds) {
  let survivors = new Set(tied)
  for (const round of rounds) {
    if (survivors.size === 1) break
    const votes = [...survivors].map((name) => round.counts.get(name))
    if (votes.every((v) => v === votes[0])) continue
    const min = votes.reduce((a, b) => (a < b ? a : b))
    survivors = new Set([...survivors].filter((name) => round.counts.get(name) === min))
  }
  return [...survivors].sort().pop()
}
"}

